CREATE TABLE IF NOT EXISTS sections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(40) NOT NULL,title VARCHAR(220) NOT NULL,eyebrow VARCHAR(220) NULL,body LONGTEXT NULL,image VARCHAR(500) NULL,button_label VARCHAR(120) NULL,button_url VARCHAR(500) NULL,theme ENUM('default','soft','dark') NOT NULL DEFAULT 'default',item_limit TINYINT UNSIGNED NOT NULL DEFAULT 6,sort_order INT NOT NULL DEFAULT 0,enabled TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY enabled_order(enabled,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
